SELECT p.subject_id, p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.dod, s.comorbidity_risk_score, s.mortality_30d, c.cardio_complications, c.neurologic_complications, s.surviving_days, p.profile_percentile_match, p.profile_percentile_control FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN stay s ON a.stay_id = s.stay_id JOIN d_icd_diagnoses d ON s.hadm_id = d.hadm_id JOIN (SELECT subject_id, COUNT(*) AS cardio_complications FROM procedures_icd WHERE icd_code IN ('42678', '42679', '42680', '42681', '42682', '42683', '42684', '42685', '42686', '42687', '42688', '42689', '42690', '42691', '42692', '42693', '42694', '42695', '42696', '42697', '42698', '42699', '42700') GROUP BY subject_id) c ON p.subject_id = c.subject_id WHERE p.gender = 'F' AND p.anchor_age BETWEEN 59 AND 69 AND s.pe_status = 'Y' AND s.comorbidity_risk_score > 5 AND s.mortality_30d < 0.5;